// @ts-strict-ignore
import { Store, UrlsForKeys } from "@/core/types/search-types";

/**
 * Each item in this helper is referenced by a _key_.
 * This is so we can have multiple indexes and stores for different things like a locale or the POIs of a parkmap.
 * A key could for some sites be just the locale (e.g. "en" or "sv").
 * But for some sites we have a more specific key like "pagesSv" or "parkmapEn"
 */
export default class SearchHelper<TStoreItem> {
  urlsForKey: UrlsForKeys;

  initializedKey: Record<string, boolean>;
  promiseForKey: Record<string, Promise<void>>;

  indexForKey: Record<string, string>;
  storeForKey: Record<string, Store<TStoreItem>>;

  private constructor() {
    this.urlsForKey = undefined;

    this.initializedKey = {};
    this.promiseForKey = {};

    this.indexForKey = {};
    this.storeForKey = {};
  }

  static instance = undefined;

  static getSingelton<TStoreItem>(): SearchHelper<TStoreItem> {
    if (!this.instance) {
      this.instance = new SearchHelper<TStoreItem>();
    }
    return this.instance as SearchHelper<TStoreItem>;
  }

  setUrls(urlsForKey: UrlsForKeys) {
    this.urlsForKey = urlsForKey;
  }

  async initializeIndex(key: string) {
    if (this.initializedKey[key]) {
      return Promise.resolve();
    }

    if (this.promiseForKey[key]) {
      return this.promiseForKey[key];
    }

    if (!this.urlsForKey) throw new Error("No urls set");
    if (!this.urlsForKey[key]) throw new Error("No urls for key" + key);

    const indexPromise = this.fetchIndex(key);
    const storePromise = this.fetchStore(key);

    this.promiseForKey[key] = Promise.all([indexPromise, storePromise]).then(([index, store]) => {
      this.indexForKey[key] = index;
      this.storeForKey[key] = store;
      this.initializedKey[key] = true;
    });

    return this.promiseForKey[key];
  }

  async fetchIndex(key: string) {
    const response = await fetch(this.urlsForKey[key].publicIndexURL);
    return response.text();
  }

  async fetchStore(key: string) {
    const response = await fetch(this.urlsForKey[key].publicStoreURL);
    return JSON.parse(await response.text()) as Store<TStoreItem>;
  }

  async getLunrData(key: string) {
    try {
      await this.initializeIndex(key);
    } catch (e) {
      console.error(e);
      return {
        index: undefined,
        store: undefined,
      };
    }

    return {
      index: this.indexForKey[key],
      store: this.storeForKey[key],
    };
  }
}
